<script>
 import {keychainWindow,keychainCapabilities} from './keychain-state.js';
 import {keychainMenus} from './keychain-menus.js';
 import {createLocalLibraryView} from './keychain-native-view.js';
 import './keychain.css';
 let {window,state: keychainState,profile,execute,registerView=()=>()=>{},available=true,active=true}=$props();
 let root=$state(),failure=$state(''),name=$state(''),account=$state(''),service=$state(''),secret=$state(''),comment=$state(''),kind=$state('password'),password=$state(''),newPassword=$state('');
 let session=$derived(keychainWindow(keychainState,window.id)),cap=$derived(keychainCapabilities(profile)),chain=$derived(keychainState.keychains.find(k=>k.id===session?.keychainId)),selected=$derived(keychainState.items.find(i=>i.id===session?.selectedId&&(!i.passwordDetails||i.passwordDetails.deletedAt===null))),rows=$derived(keychainState.items.filter(i=>(!i.passwordDetails||i.passwordDetails.deletedAt===null)&&i.keychainId===session?.keychainId&&(session?.category==='all'||i.kind===session?.category)&&[i.name,i.account,i.service,i.comment].join(' ').toLowerCase().includes(session?.search.toLowerCase()??''))),menus=$derived(keychainMenus({session,keychain:chain,selected,preferences:keychainState.preferences,classic:cap.classic}));
 async function run(suffix,payload={}){if(!root?.isConnected||!available||!active)return;const mounted=root,originalSession=session,result=await execute(`keychain.${suffix}`,{windowId:window.id},payload);if(root===mounted&&session===originalSession)failure=result?.status==='rejected'?result.error?.message??'Operation unavailable.':'';return result;}
 async function menu(item){if(!item.enabled||!item.request)return;await run('menu',{menu:null});await run(item.request.command.slice(9),item.request.payload);}
 function loadEditor(){name=selected?.name??'';account=selected?.account??'';service=selected?.service??'';secret=selected?.passwordDetails?.type==='passkey'?'':selected?.secret??'';comment=selected?.comment??'';kind=selected?.kind==='secure-note'?'secure-note':'password';}
 $effect(()=>{const panel=session?.panel;if(panel==='edit')loadEditor();if(panel==='new'){name='';account='';service='';secret='';comment='';kind='password';}password='';newPassword='';});
 $effect(()=>{if(!root||!session)return;const id=window.id,view=createLocalLibraryView({root,getRoot:()=>root,getSession:()=>keychainWindow(keychainState,id),available:()=>available&&active&&root?.isConnected===true});const unregister=registerView(id,view);return ()=>{view.dispose();if(typeof unregister==='function')unregister();else registerView(id,null,view);};});
 async function drop(event){event.preventDefault();let id=event.dataTransfer.getData('application/x-jesteros-file-id');if(!id){try{id=JSON.parse(event.dataTransfer.getData('application/x-jesteros-file-ids'))[0];}catch{}}if(id)await run('import',{fileId:id});}
</script>
{#if session}
<section bind:this={root} class:classic={cap.classic} class:win={cap.windows} class:golden={cap.golden} class="keychain-native" aria-label={cap.windows?'Local Keychain':'Keychain Access'} ondragover={event=>event.preventDefault()} ondrop={drop}>
 <nav class="library-menubar" aria-label="Application menus">{#each menus as m}<button data-library-control={'menu-'+m.id} class:active={session.menu===m.id} onclick={()=>run('menu',{menu:session.menu===m.id?null:m.id})}>{m.label}</button>{/each}</nav>
 {#if session.menu}<div class="library-menu" role="menu">{#each menus.find(m=>m.id===session.menu)?.children??[] as item}<button role="menuitem" data-library-control={'action-'+item.label} disabled={!item.enabled} onclick={()=>menu(item)}>{item.label}</button>{/each}</div>{/if}
 <header class="library-toolbar"><button data-library-control="lock" onclick={()=>run(chain.locked?'panel':'keychain',chain.locked?{panel:'unlock'}:{operation:'lock'})}>{chain.locked?'🔒 Unlock':'🔓 Lock'}</button><button data-library-control="add" disabled={chain.locked} onclick={()=>run('panel',{panel:'new'})}>＋</button><button data-library-control="info" disabled={!selected} onclick={()=>run('panel',{panel:'inspect'})}>ⓘ</button><span class="toolbar-spacer"></span><input data-library-control="search" aria-label="Search keychain" type="search" placeholder="Search" value={session.search} oninput={e=>run('navigate',{search:e.currentTarget.value})}/></header>
 <div class="keychain-workspace"><aside><h3>Keychains</h3>{#each keychainState.keychains as k}<button data-library-control={'chain-'+k.id} class:chosen={session.keychainId===k.id} onclick={()=>run('navigate',{keychainId:k.id})}>{k.locked?'🔒':'🔓'} {k.name}</button>{/each}<h3>Category</h3>{#each [['all','All Items'],['password',cap.golden?'Passwords (local)':'Passwords'],['secure-note','Secure Notes'],['identity','My Certificates'],['key','Keys'],['certificate','Certificates']] as category}<button data-library-control={'category-'+category[0]} class:chosen={session.category===category[0]} onclick={()=>run('navigate',{category:category[0]})}>{category[1]}</button>{/each}</aside>
 <main><div class="keychain-table-head"><span>Name</span><span>Kind</span><span>Account</span></div><div class="keychain-items">{#each rows as row}<button class:selected={selected===row} data-library-control={'item-'+row.id} onclick={()=>run('navigate',{selectedId:row.id})} ondblclick={()=>run('panel',{panel:'inspect'})}><span>{row.kind==='certificate'?'▣':row.kind==='secure-note'?'▤':'⚿'} {row.name}</span><span>{row.kind==='password'?row.passwordDetails.type==='passkey'?'local passkey':row.passwordDetails.type==='wifi'?'network password':'application password':row.kind==='secure-note'?'secure note':'certificate'}</span><span>{row.account}</span></button>{/each}{#if !rows.length}<p class="empty-state">No items match this category and search.</p>{/if}</div></main></div>
 <footer>{keychainState.preferences.showStatus?`${rows.length} items · ${chain.locked?'Keychain locked':'Keychain unlocked'}`:''}<span role="status">{failure||session.status}</span></footer>
 <details class="library-disclosure"><summary>Local scope and security</summary><p>{cap.availability}</p><p>Invented unlock passwords: login = trail-demo; System = system-demo. No real credentials.</p></details>
 {#if session.panel!=='none'}<div class="library-sheet-backdrop"><section class="library-sheet" role="dialog" aria-modal="true" aria-label={session.panel==='inspect'?selected?.name??'Item information':session.panel}>
 <header><h2>{session.panel==='inspect'?selected?.name??'Item information':session.panel==='new'?'New Password Item':session.panel==='edit'?'Edit Item':session.panel==='unlock'?`Unlock “${chain.name}”`:session.panel==='reveal'?'Confirm Local Secret Access':session.panel==='generator'?'Password Assistant':session.panel==='new-keychain'?'New Keychain':'Keychain Access '+(cap.classic?'Preferences':'Settings')}</h2><button data-library-control="sheet-close" onclick={()=>run('panel',{panel:'none'})}>×</button></header>
 {#if session.panel==='unlock'}<p>This is an invented local scene password, not system authentication.</p><label>Password<input data-library-control="unlock-password" type="password" bind:value={password}/></label><button data-library-control="unlock-confirm" onclick={()=>run('keychain',{operation:'unlock',password})}>Unlock</button>
 {:else if session.panel==='reveal'}<p>Confirm access using the invented password for “{chain.name}”. This is a local scene challenge, not host authentication.</p><label>Invented keychain password<input data-library-control="reveal-password" type="password" bind:value={password}/></label><button data-library-control="reveal-confirm" disabled={chain.locked||!selected} onclick={()=>run('item',{operation:'reveal',itemId:selected?.id,password})}>Show Secret</button>
 {:else if session.panel==='new-keychain'}<label>Name<input data-library-control="new-chain-name" bind:value={name}/></label><label>Invented password<input data-library-control="new-chain-password" type="password" bind:value={password}/></label><button data-library-control="create-chain" onclick={()=>run('keychain',{operation:'create',name,password})}>Create</button>
 {:else if session.panel==='new'||session.panel==='edit'}
 {#if chain.locked||session.panel==='edit'&&selected?.kind!=='certificate'&&selected?.passwordDetails?.type!=='passkey'&&selected?.access.confirm&&!session.revealed}<p>{chain.locked?'Unlock this local keychain before viewing or editing its invented secrets.':'Confirm local secret access again after the keychain was locked or its policy changed.'}</p>{#if !chain.locked}<button data-library-control="edit-reconfirm" onclick={()=>run('panel',{panel:'reveal'})}>Confirm Access…</button>{/if}{:else}
 <label>Kind<select data-library-control="item-kind" bind:value={kind} disabled={session.panel==='edit'}><option value="password">Password</option><option value="secure-note">Secure Note</option></select></label><label>Name<input data-library-control="item-name" bind:value={name}/></label><label>Account<input data-library-control="item-account" bind:value={account}/></label><label>Where<input data-library-control="item-service" bind:value={service}/></label>{#if session.panel==='new'||selected?.kind!=='certificate'&&selected?.passwordDetails?.type!=='passkey'}<label>Invented secret<textarea data-library-control="item-secret" bind:value={secret}></textarea></label>{/if}<label>Comments<textarea data-library-control="item-comment" bind:value={comment}></textarea></label><button data-library-control="item-save" disabled={chain.locked} onclick={()=>run('item',{operation:session.panel==='new'?'create':'update',...(session.panel==='new'?{kind}:{itemId:selected?.id}),name,account,service,comment,...(session.panel==='edit'&&(selected?.kind==='certificate'||selected?.passwordDetails?.type==='passkey')?{}:{secret})})}>Save</button>
 {/if}
 {:else if session.panel==='inspect'}
 {#if selected}<dl><dt>Kind</dt><dd>{selected.kind}</dd><dt>Account</dt><dd>{selected.account||'—'}</dd><dt>Where</dt><dd>{selected.service||'—'}</dd><dt>Comments</dt><dd>{selected.comment}</dd></dl>
 {#if selected.kind==='certificate'}<details open><summary>Certificate details</summary><dl>{#each Object.entries(selected.certificate) as [key,value]}<dt>{key}</dt><dd>{value}</dd>{/each}<dt>SHA-256</dt><dd>{selected.fingerprint}</dd></dl><p>No signature or chain verification. Local trust metadata only.</p></details><fieldset disabled={chain.locked}><legend>Trust</legend>{#each [['ssl','Secure Sockets Layer'],['email','Secure Mail'],['codeSigning','Code Signing']] as policy}<label>{policy[1]}<select data-library-control={'trust-'+policy[0]} value={selected.trust[policy[0]]} onchange={e=>run('item',{operation:'trust',itemId:selected.id,[policy[0]]:e.currentTarget.value})}><option value="system">Use System Defaults (local)</option><option value="always">Always Trust (local)</option><option value="never">Never Trust (local)</option></select></label>{/each}</fieldset><div class="sheet-actions"><button data-library-control="export-pem" disabled={chain.locked} onclick={()=>run('export',{itemId:selected.id,format:'pem'})}>Export PEM…</button><button data-library-control="export-der" disabled={chain.locked} onclick={()=>run('export',{itemId:selected.id,format:'der'})}>Export DER…</button></div>
 {:else if selected.passwordDetails?.type==='passkey'}<p>Cryptographic local P-256 passkey. Private material is not a text password and cannot be shown or copied here. Use Passwords to sign a local challenge.</p><dl><dt>Credential ID</dt><dd>{selected.passwordDetails.passkey.credentialId}</dd><dt>Verified assertions</dt><dd>{selected.passwordDetails.passkey.signCount}</dd></dl>
 {:else}<label class="check"><input data-library-control="show-password" type="checkbox" checked={session.revealed&&!chain.locked} disabled={chain.locked} onchange={e=>e.currentTarget.checked&&selected.access.confirm?run('panel',{panel:'reveal'}):run('item',{operation:e.currentTarget.checked?'reveal':'hide',itemId:selected.id})}/>Show {selected.kind==='secure-note'?'note':'password'}</label><output class="secret-output">{session.revealed&&!chain.locked?selected.secret:'••••••••'}</output><button data-library-control="copy-secret" disabled={!session.revealed||chain.locked} onclick={()=>run('copy',{itemId:selected.id})}>Copy Secret</button>{/if}
 <fieldset disabled={chain.locked}><legend>Access Control — local policy only</legend><label class="check"><input data-library-control="access-confirm" type="checkbox" checked={selected.access.confirm} onchange={e=>run('item',{operation:'access',itemId:selected.id,confirm:e.currentTarget.checked})}/>Confirm access</label><label>Allowed local app IDs<input data-library-control="allowed-apps" value={selected.access.allowedApps.join(', ')} onchange={e=>run('item',{operation:'access',itemId:selected.id,allowedApps:[...new Set(e.currentTarget.value.split(',').map(s=>s.trim()).filter(Boolean))]})}/></label></fieldset>
 <div class="sheet-actions"><button data-library-control="edit-item" disabled={chain.locked} onclick={()=>run('panel',{panel:selected.kind!=='certificate'&&selected.passwordDetails?.type!=='passkey'&&selected.access.confirm&&!session.revealed?'reveal':'edit'})}>Edit…</button><button data-library-control="delete-item" disabled={chain.locked} onclick={()=>run('item',{operation:'delete',itemId:selected.id})}>Delete Item</button></div>{:else}<p>Select an actual item first.</p>{/if}
 {:else if session.panel==='generator'}<p>Unbiased Web Crypto random generation. Generated passwords remain local plaintext scene data.</p><label>Length<input data-library-control="password-length" type="number" min="8" max="128" value={keychainState.preferences.generatorLength} onchange={e=>run('preferences',{generatorLength:Number(e.currentTarget.value)})}/></label><button data-library-control="generate" onclick={()=>run('generate',{})}>Generate</button><output class="secret-output">{session.generated||'Click Generate'}</output><button data-library-control="use-generated" disabled={!session.generated||chain.locked} onclick={()=>{secret=session.generated;name='Generated local password';account='';service='';comment='';run('item',{operation:'create',kind:'password',name,secret});}}>Save as New Item</button>
 {:else}<p>{cap.availability}</p><label class="check"><input data-library-control="show-status" type="checkbox" checked={keychainState.preferences.showStatus} onchange={e=>run('preferences',{showStatus:e.currentTarget.checked})}/>Show status bar</label><label class="check"><input data-library-control="lock-quit" type="checkbox" checked={keychainState.preferences.lockOnQuit} onchange={e=>run('preferences',{lockOnQuit:e.currentTarget.checked})}/>Lock local keychains on quit</label><fieldset><legend>Selected keychain</legend><label>Name<input data-library-control="chain-name" value={chain.name} onchange={e=>run('keychain',{operation:'rename',name:e.currentTarget.value})} disabled={chain.locked}/></label><label>Current invented password<input data-library-control="current-password" type="password" bind:value={password}/></label><label>New invented password<input data-library-control="new-password" type="password" bind:value={newPassword}/></label><button data-library-control="change-chain-password" disabled={chain.locked} onclick={()=>run('keychain',{operation:'password',password,newPassword})}>Change Password</button></fieldset>{/if}
 {#if failure}<p class="library-error" role="alert">{failure}</p>{/if}</section></div>{/if}
</section>{/if}
